class BridgeHandler(BaseHTTPRequestHandler):
    bridge = None  # set on server initialization
    timeout = 5.0  # Server-side request read timeout in seconds (strictly <= 8s)
    MAX_BODY_SIZE = 1024 * 1024  # 1 MB body size limit

    def log_message(self, format, *args):
        # Silent logger to prevent console noise
        pass

    def send_json_response(self, code, data):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    def do_GET(self):
        parsed = urlsplit(self.path)
        path = parsed.path.rstrip("/")
        params = parse_qs(parsed.query)

        try:
            if path in ("", "/ping", "/api/ping"):
                self.send_json_response(200, {"status": "ok", "app": str(self.bridge.app_dir), "version": self.bridge.version})
            elif path in ("/channels", "/api/channels"):
                data = self.bridge.call("catalog.get_channels")
                self.send_json_response(200, data)
            elif path in ("/list", "/api/list"):
                ch = params.get("channel", ["20"])[0]
                pg = params.get("page", ["1"])[0]
                channel_val = int(ch) if ch.isdigit() else ch
                page_val = int(pg) if pg.isdigit() else 1
                data = self.bridge.call("catalog.get_video_list", {"channel": channel_val, "page": page_val})
                self.send_json_response(200, data)
            elif path in ("/search", "/api/search"):
                key = params.get("key", [""])[0]
                pg = params.get("page", ["1"])[0]
                data = self.bridge.call("catalog.search_video", {"key": key, "page": str(pg)})
                self.send_json_response(200, data)
            elif path in ("/detail", "/api/detail"):
                vid = params.get("id", [""])[0]
                if not vid:
                    self.send_json_response(400, {"error": "Missing id parameter"})
                    return
                data = self.bridge.call("catalog.get_video_detail", {"id": str(vid)})
                self.send_json_response(200, data)
            elif path in ("/play", "/api/play"):
                vid = params.get("id", [""])[0]
                part = params.get("part", [""])[0]
                play_line = params.get("play", [""])[0]
                if not vid or not part:
                    self.send_json_response(400, {"error": "Missing id or part parameter"})
                    return
                payload = {"id": str(vid), "part": str(part), "play": str(play_line), "resolve": True}
                data = self.bridge.call("video.play", payload)
                self.send_json_response(200, data)
            else:
                self.send_json_response(404, {"error": f"Unknown path: {path}"})
        except (socket.timeout, TimeoutError):
            try:
                self.send_json_response(408, {"error": "Request Timeout"})
            except Exception:
                pass
            self.close_connection = True
        except Exception as e:
            self.send_json_response(500, {"error": str(e)})

    def do_POST(self):
        parsed = urlsplit(self.path)
        path = parsed.path.rstrip("/")
        try:
            try:
                length_hdr = self.headers.get("Content-Length", 0)
                length = int(length_hdr)
            except (ValueError, TypeError):
                self.send_json_response(400, {"error": "Invalid Content-Length header"})
                return

            if length < 0:
                self.send_json_response(400, {"error": "Negative Content-Length header"})
                return

            if length > self.MAX_BODY_SIZE:
                self.send_json_response(413, {"error": "Payload Too Large"})
                self.close_connection = True
                return

            body = self.rfile.read(length) if length > 0 else b"{}"
            payload_data = json.loads(body.decode("utf-8")) if body else {}

            if path in ("/call", "/api/call"):
                cmd = payload_data.get("command")
                payload = payload_data.get("payload", {})
                if not cmd:
                    self.send_json_response(400, {"error": "Missing command in POST body"})
                    return
                data = self.bridge.call(cmd, payload)
                self.send_json_response(200, data)
            elif path in ("/search", "/api/search"):
                key = payload_data.get("key", "")
                pg = payload_data.get("page", "1")
                data = self.bridge.call("catalog.search_video", {"key": key, "page": str(pg)})
                self.send_json_response(200, data)
            elif path in ("/list", "/api/list"):
                ch = payload_data.get("channel", 20)
                pg = payload_data.get("page", 1)
                data = self.bridge.call("catalog.get_video_list", {"channel": int(ch), "page": int(pg)})
                self.send_json_response(200, data)
            elif path in ("/detail", "/api/detail"):
                vid = payload_data.get("id", "")
                data = self.bridge.call("catalog.get_video_detail", {"id": str(vid)})
                self.send_json_response(200, data)
            elif path in ("/play", "/api/play"):
                vid = payload_data.get("id", "")
                part = payload_data.get("part", "")
                play_line = payload_data.get("play", "")
                payload = {"id": str(vid), "part": str(part), "play": str(play_line), "resolve": True}
                data = self.bridge.call("video.play", payload)
                self.send_json_response(200, data)
            else:
                self.send_json_response(404, {"error": f"Unknown path: {path}"})
        except (socket.timeout, TimeoutError):
            try:
                self.send_json_response(408, {"error": "Request Timeout"})
            except Exception:
                pass
            self.close_connection = True
        except json.JSONDecodeError as e:
            self.send_json_response(400, {"error": f"Invalid JSON payload: {e}"})
        except Exception as e:
            self.send_json_response(500, {"error": str(e)})
